import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import type { Cell, Clip, LayoutParams, LayoutType, Session, Slot } from '../types/session';
import { DEFAULT_FX, DEFAULT_LAYOUT_PARAMS } from '../types/session';
import { makeSession } from './testFixtures';
import { beatToFrame, cellTiming, cellZoom, layoutRegions, shakeOffset, sourceTime } from './timing';

// Generated by backend/tests/test_parity.py — the export compiler's timing.
const fixture = JSON.parse(
  readFileSync(resolve(__dirname, '../../../shared/fixtures/timing_parity.json'), 'utf8'),
);

const session = (bpm: number, fps: number): Session => makeSession({ fps }, { bpm });

describe('timing parity with backend', () => {
  it('maps cells to source time identically', () => {
    for (const c of fixture.cases) {
      const slot: Slot = {
        layout: 'FULLSCREEN_VELOCITY', layout_params: DEFAULT_LAYOUT_PARAMS, locked: false, cells: [],
        ...c.slot, fx: { ...DEFAULT_FX, ...c.slot.fx },
      };
      const cell: Cell = c.cell;
      const clip: Clip = { energy_tag: 1, focus_xy: [0.5, 0.5], ...c.clip };
      const t = cellTiming(session(c.bpm, c.fps), slot, cell, clip);
      expect(t.startFrame).toBe(c.start_frame);
      expect(t.endFrame).toBe(c.end_frame);
      expect(t.scale).toBeCloseTo(c.scale, 9);
      for (const [f, s] of c.samples) expect(sourceTime(t, f, c.fps)).toBeCloseTo(s, 9);
    }
  });

  it('computes identical layout regions', () => {
    for (const [key, expected] of Object.entries(fixture.regions)) {
      const [layout, params, size] = key.split('|');
      const [w, h] = size.split('x').map(Number);
      const p: LayoutParams = { ...DEFAULT_LAYOUT_PARAMS, ...JSON.parse(params) };
      expect(layoutRegions(layout as LayoutType, p, w, h)).toEqual(expected);
    }
  });

  it('computes identical push / bounce / shake motion', () => {
    expect(fixture.motion.length).toBeGreaterThan(0);
    for (const m of fixture.motion) {
      expect(cellZoom(m.t, m.dur, m.bounce, m.push, m.shake)).toBeCloseTo(m.zoom, 12);
      const [dx, dy] = shakeOffset(m.t);
      expect(dx).toBeCloseTo(m.shake_offset[0], 12);
      expect(dy).toBeCloseTo(m.shake_offset[1], 12);
    }
  });

  it('rounds beats to frames identically', () => {
    for (const [key, frame] of Object.entries(fixture.beat_frames)) {
      const [b, bpm, fps] = key.split('|').map(Number);
      expect(beatToFrame(b, bpm, fps)).toBe(frame);
    }
  });
});
